def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in version_without_build:
            core_part, prerelease_part = version_without_build.split('-', 1)
        else:
            core_part = version_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            # Convert to comparable tuples: (is_numeric, numeric_value_or_string)
            prerelease = tuple(
                (True, int(id)) if id.isdigit() else (False, id)
                for id in identifiers
            )
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def compare_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # For sorting:
        # - Compare major, minor, patch numerically
        # - Version without prerelease sorts after version with prerelease
        #   So we use (False,) for no prerelease (sorts after) and (True, prerelease) for with prerelease
        # - Pre-release identifiers: numeric sorts before non-numeric, then by value

        if prerelease is None:
            # No pre-release: sorts after any pre-release of same version
            prerelease_key = (False,)
        else:
            # Has pre-release: sorts before any non-pre-release of same version
            prerelease_key = (True, prerelease)

        return (major, minor, patch, prerelease_key)

    # Sort with stable sort (preserves input order for equal elements)
    return sorted(versions, key=compare_key)

